const clearFoto=()=>{foto.value='';preview.removeAttribute('src');selected.classList.add('d-none');selected.classList.remove('d-flex')},setFoto=file=>{if(!file||!file.type.startsWith('image/')){message('Selecione ou cole um arquivo de imagem válido.','warning');return}if(file.size>5242880){message('A foto deve ter no máximo 5 MB.','warning');return}const transfer=new DataTransfer();transfer.items.add(file);foto.files=transfer.files;preview.src=URL.createObjectURL(file);fotoNome.textContent=file.name||'Imagem colada';selected.classList.remove('d-none');selected.classList.add('d-flex')};
