document.getElementById('selecionarFoto').addEventListener('click',()=>foto.click());document.getElementById('removerFoto').addEventListener('click',clearFoto);foto.addEventListener('change',()=>setFoto(foto.files[0]));paste.addEventListener('paste',event=>{event.preventDefault();const file=[...event.clipboardData.items].find(item=>item.type.startsWith('image/'))?.getAsFile();setFoto(file)});drop.addEventListener('dragover',event=>{event.preventDefault();drop.classList.add('is-dragging')});drop.addEventListener('dragleave',()=>drop.classList.remove('is-dragging'));drop.addEventListener('drop',event=>{event.preventDefault();drop.classList.remove('is-dragging');setFoto(event.dataTransfer.files[0])});
document.getElementById('orcamentoForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf},body:new FormData(form)});if(!response.ok)await errors(response);const body=await response.json();form.reset();clearFoto();imageMode();orcamentos.ajax.reload();message(body.message)}catch(error){message(error.message,'danger')}finally{button.disabled=false}});document.getElementById('orcamentosTable').addEventListener('click',async event=>{const button=event.target.closest('.excluir-orcamento');if(!button||!confirm('Excluir esta requisição de orçamento?'))return;try{const response=await fetch(button.dataset.url,{method:'DELETE',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf}});if(!response.ok)await errors(response);orcamentos.ajax.reload();message((await response.json()).message)}catch(error){message(error.message,'danger')}});
const produto=document.getElementById('compra_id'),quantidadeDespesa=document.getElementById('quantidade_despesa'),custoDespesa=document.getElementById('custo_despesa'),unidadeDespesa=document.getElementById('unidadeDespesa'),estoqueDespesa=document.getElementById('estoqueDespesa'),currency=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(value)||0),calculateCusto=()=>{const preco=Number(produto.selectedOptions[0]?.dataset.preco||0),quantidade=Number(quantidadeDespesa.value||0);custoDespesa.value=currency(preco*quantidade)};const updateProduto=()=>{const option=produto.selectedOptions[0],unidade=option?.dataset.unidade||'',estoque=Number(option?.dataset.estoque||0);quantidadeDespesa.step=unidade==='un'?'1':'0.1';quantidadeDespesa.min=unidade==='un'?'1':'0.1';quantidadeDespesa.max=estoque||'';unidadeDespesa.textContent=unidade||'—';estoqueDespesa.textContent=option?.value?`${estoque.toLocaleString('pt-BR')} ${unidade} disponíveis`:'';estoqueDespesa.classList.toggle('d-none',!option?.value);calculateCusto()};const updateEstoque=(id,estoque)=>{const option=produto.querySelector(`option[value="${id}"]`);if(!option||estoque===null)return;const value=produto.value;option.dataset.estoque=estoque;option.textContent=option.textContent.replace(/Estoque [^•]+$/,`Estoque ${Number(estoque).toLocaleString('pt-BR')} ${option.dataset.unidade}`);$(produto).select2('destroy').select2({theme:'bootstrap-5',width:'100%',dropdownParent:$('#etapasModal'),placeholder:'Selecione ou pesquise'}).val(value).trigger('change.select2');updateProduto()};$(produto).on('change',updateProduto);quantidadeDespesa.addEventListener('input',calculateCusto);updateProduto();
document.getElementById('despesaForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf},body:new FormData(form)});if(!response.ok)await errors(response);const body=await response.json();updateEstoque(body.compra_id,body.estoque);quantidadeDespesa.value='';despesas.ajax.reload();message(body.message)}catch(error){message(error.message,'danger')}finally{button.disabled=false}});document.getElementById('despesasTable').addEventListener('click',async event=>{const button=event.target.closest('.excluir-despesa');if(!button||!confirm('Excluir esta despesa e devolver a quantidade ao estoque?'))return;try{const response=await fetch(button.dataset.url,{method:'DELETE',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf}});if(!response.ok)await errors(response);const body=await response.json();updateEstoque(body.compra_id,body.estoque);despesas.ajax.reload();message(body.message)}catch(error){message(error.message,'danger')}});
const etapaDoisForm=document.getElementById('etapaDoisForm'),dataInicio=document.getElementById('data_inicio'),horaInicio=document.getElementById('hora_inicio'),marcarInicio=document.getElementById('marcarInicio');let inicioSalvo=@json((bool)$proximoLancamento->data_inicio);const now=()=>{const date=new Date(),part=value=>String(value).padStart(2,'0');dataInicio.value=`${date.getFullYear()}-${part(date.getMonth()+1)}-${part(date.getDate())}`;horaInicio.value=`${part(date.getHours())}:${part(date.getMinutes())}`};const saveEtapaDois=async(avancar,button)=>{button.disabled=true;try{const response=await fetch(etapaDoisForm.action,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf},body:new FormData(etapaDoisForm)});if(!response.ok)await errors(response);inicioSalvo=true;horaInicio.classList.remove('is-invalid');message((await response.json()).message);if(avancar)bootstrap.Tab.getOrCreateInstance(document.getElementById('etapa-3-tab')).show()}catch(error){message(error.message,'danger')}finally{button.disabled=false}};marcarInicio.addEventListener('click',()=>{now();saveEtapaDois(false,marcarInicio)});etapaDoisForm.addEventListener('submit',event=>{event.preventDefault();saveEtapaDois(true,etapaDoisForm.querySelector('[type=submit]'))});document.querySelectorAll('#etapa-3-tab,#etapa-4-tab').forEach(tab=>tab.addEventListener('click',event=>{if(inicioSalvo)return;event.preventDefault();event.stopImmediatePropagation();bootstrap.Tab.getOrCreateInstance(document.getElementById('etapa-2-tab')).show();horaInicio.classList.add('is-invalid');message('Registre e salve o horário de início antes de avançar para a próxima etapa.','warning');setTimeout(()=>{horaInicio.focus();horaInicio.select()},150)}));
document.getElementById('conclusaoForm').addEventListener('submit',async event=>{event.preventDefault();if(!confirm('Confirma a conclusão e o arquivamento desta manutenção?'))return;const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;try{const response=await fetch(form.action,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':csrf},body:new FormData(form)});if(!response.ok)await errors(response);const body=await response.json();window.location.href=body.redirect}catch(error){message(error.message,'danger');button.disabled=false}});
